-- Template de l'email envoye quand un creneau a ete vendu deux fois.
--
-- Le webhook Stripe rembourse la cliente automatiquement (voir 4-7) ; sans cet
-- email elle constate un debit puis un credit inexpliques, et croit avoir une
-- consultation reservee.
--
-- INSERT seul, jamais UPDATE : les templates sont editables depuis l'admin et
-- une migration qui les reecrirait effacerait le travail de Carole (regle 6-5).
-- Ce fichier est verifie par src/lib/emails/migration-guard.spec.ts.

-- `name` n'avait aucune contrainte d'unicite, alors que getTemplate() fait un
-- .single() dessus : deux templates homonymes auraient fait echouer la lecture,
-- donc l'envoi, en silence. L'index sert aussi au ON CONFLICT ci-dessous.
CREATE UNIQUE INDEX IF NOT EXISTS email_templates_name_unique
  ON email_templates (name);

